package dev.riserecode;

import dev.riserecode.cosmetics.*;
import dev.riserecode.setting.*;
import dev.riserecode.ui.clickgui.ClickGui;
import dev.riserecode.ui.component.*;
import dev.riserecode.ui.menu.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicBoolean;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.input.KeyEvent;

/** Direct failures and deliberately delayed imports across newer user intent and retained children. */
public final class UxAsyncRecoveryIntegrationTest {
    private static int checks;
    private static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static Object field(Object owner,String name){try{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static CosmeticsEditor editor(){return Client.INSTANCE.getClickGui().getCosmeticsEditor();}
    private static ActionButton importer(){return (ActionButton)field(editor(),"importButton");}
    private static TextField path(){return (TextField)field(editor(),"importPath");}
    private static String message(){return field(Client.INSTANCE.getClickGui(),"message").toString();}
    private static void press(ClientGameTestContext c,String label){for(int i=0;i<40;i++){if(c.computeOnClient(mc->mc.gui.screen().getFocused() instanceof Button b&&b.getMessage().getString().startsWith(label))){c.getInput().pressKey(257);c.waitTicks(2);return;}c.getInput().pressKey(258);c.waitTick();}throw new AssertionError("Cannot focus "+label);}
    private static CountDownLatch hold(ClientGameTestContext c){var latch=new CountDownLatch(1);var started=new AtomicBoolean();c.runOnClient(mc->editor().manager().library().work(()->{started.set(true);latch.await();return true;}));c.waitFor(mc->started.get(),200);return latch;}
    private record Asset(Path path,String id){}
    private static Asset png(int color){try{var image=new java.awt.image.BufferedImage(64,32,java.awt.image.BufferedImage.TYPE_INT_ARGB);for(int y=0;y<32;y++)for(int x=0;x<64;x++)image.setRGB(x,y,color);var bytes=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"PNG",bytes);image.flush();var path=Files.createTempFile("ux-async-cape-",".png");Files.write(path,bytes.toByteArray());return new Asset(path,"import-"+CosmeticsLibrary.hash(bytes.toByteArray()));}catch(Exception e){throw new RuntimeException(e);}}
    private static void waitFor(ClientGameTestContext c,Asset asset,Object owner){c.waitFor(mc->editor().manager().library().find(asset.id())!=null&&!((Boolean)field(owner,"importing")),400);c.waitTicks(5);}
    private static CosmeticDetailsScreen details(ClientGameTestContext c){return c.computeOnClient(mc->{var details=new CosmeticDetailsScreen(Client.INSTANCE.getClickGui(),editor());mc.gui.setScreen(details);return details;});}
    public static void run(ClientGameTestContext c){
        c.waitFor(mc->Client.INSTANCE.isInitialized()&&Client.INSTANCE.resourcesReady()&&mc.gui.overlay()==null,1200);c.getInput().resizeWindow(1280,960);c.runOnClient(mc->{mc.options.guiScale().set(2);var theme=Client.INSTANCE.getThemeManager();theme.reset();((BooleanSetting)theme.getSetting("Reduced Motion")).setValue(true);((DoubleSetting)theme.getSetting("Window Width")).setValue(520.0);((DoubleSetting)theme.getSetting("Window Height")).setValue(400.0);var gui=Client.INSTANCE.getClickGui();gui.open(null);gui.selectPage(ClickGui.Page.COSMETICS);editor().discard();editor().category(CosmeticCategory.CAPE);});c.waitTicks(5);
        var initial=c.computeOnClient(mc->editor().draft());c.runOnClient(mc->{path().setValue("");importer().activate();check(message().contains("Enter a valid PNG")&&((ActionButton)field(editor(),"importStatusDetails")).label().contains("Import failed")&&importer().isEnabled(),"Empty-path validation is visible and leaves import available");});c.runOnClient(mc->{path().setValue("/missing/ux-async-cape.png");Client.INSTANCE.getClickGui().showNotice("Prior message");importer().activate();});c.waitTicks(12);c.takeScreenshot("ux13-root-import-failure");
        c.runOnClient(mc->{check(message().contains("Import failed")&&message().contains("File not found")&&message().contains("ux-async-cape.png"),"A direct missing-file failure is visible with its actual cause");check(editor().draft().equals(initial)&&path().getValue().equals("/missing/ux-async-cape.png")&&importer().isEnabled(),"Failed import preserves path/outfit and permits retry");});
        c.runOnClient(mc->{var status=(ActionButton)field(editor(),"importStatusDetails");check(status.label().contains("Import failed")&&status.getBounds().y()+status.getBounds().height()<=path().getBounds().y(),"Inline import failure is visible above the path without covering it");});UxAuxiliaryIntegrationTest.focus(c,"Cape import status.");c.getInput().pressKey(257);c.waitTicks(3);c.runOnClient(mc->check(mc.gui.screen() instanceof InfoScreen&&((InfoScreen)mc.gui.screen()).text().contains("ux-async-cape.png"),"Inline failure opens its complete cause with keyboard"));c.takeScreenshot("ux13-root-import-full-error");c.getInput().pressKey(256);c.waitTicks(3);c.runOnClient(mc->check(path().getValue().equals("/missing/ux-async-cape.png")&&Client.INSTANCE.getClickGui().focusedControlLabel().startsWith("Cape import status."),"Full import error returns to its opener and preserves the path"));
        var success=png(0xFFE93A1E);var held=hold(c);try{c.runOnClient(mc->{path().setValue(success.path().toString());importer().activate();editor().turn(15);});c.waitTicks(2);c.runOnClient(mc->check(!importer().isEnabled()&&importer().label().contains("Importing"),"Pending root import has visible progress and prevents duplicates"));var waiting=details(c);c.waitTicks(2);c.runOnClient(mc->check(!((Button)field(waiting,"importButton")).active&&waiting.fullStatus().contains("Importing"),"Switching acquisition routes retains one shared pending import"));press(c,"Back to outfit");c.runOnClient(mc->((ActionButton)field(editor(),"importStatusDetails")).activate());c.waitTicks(2);}finally{held.countDown();}waitFor(c,success,editor());c.runOnClient(mc->check(mc.gui.screen() instanceof InfoScreen&&editor().selectedId().equals(success.id()),"Reading retained inline status keeps the original import intent active"));c.getInput().pressKey(256);c.waitTicks(3);
        c.runOnClient(mc->{check(editor().selectedId().equals(success.id())&&message().contains("selected in draft"),"Successful current import selects the draft and describes the result");check(!editor().manager().outfit().equals(editor().draft()),"Import does not apply the outfit");editor().discard();editor().category(CosmeticCategory.CAPE);});
        var newer=png(0xFF83B7E1);held=hold(c);CosmeticLoadout[] wanted={null};try{c.runOnClient(mc->{path().setValue(newer.path().toString());importer().activate();editor().select("pet-bee");wanted[0]=editor().draft();});}finally{held.countDown();}waitFor(c,newer,editor());c.runOnClient(mc->{check(editor().selectedId().equals("pet-bee")&&editor().draft().equals(wanted[0]),"Late root import cannot overwrite a newer item/category draft");check(message().contains("library")&&message().contains("unchanged"),"Late completion explains library-only import");});
        var changedPath=png(0xFF345287);held=hold(c);try{c.runOnClient(mc->{editor().discard();editor().category(CosmeticCategory.CAPE);wanted[0]=editor().draft();path().setValue(changedPath.path().toString());importer().activate();path().setValue("/next/path.png");});}finally{held.countDown();}waitFor(c,changedPath,editor());c.runOnClient(mc->{check(editor().draft().equals(wanted[0])&&path().getValue().equals("/next/path.png"),"Changing the path while pending prevents late selection and retains the newer path");editor().select("pet-bee");wanted[0]=editor().draft();});
        var closed=png(0xFFC893A8);var closedChild=details(c);held=hold(c);try{c.runOnClient(mc->closedChild.path().setValue(closed.path().toString()));press(c,"Import PNG");press(c,"Back to outfit");}finally{held.countDown();}waitFor(c,closed,closedChild);c.runOnClient(mc->check(editor().selectedId().equals("pet-bee")&&editor().draft().equals(wanted[0])&&mc.gui.screen()==Client.INSTANCE.getClickGui(),"Returning from acquisition before completion retains the existing dirty outfit"));
        var nested=png(0xFF81A36B);var active=details(c);held=hold(c);try{c.runOnClient(mc->active.path().setValue(nested.path().toString()));press(c,"Import PNG");c.runOnClient(mc->check(!((Button)field(active,"importButton")).active&&active.fullStatus().contains("Importing"),"Retained acquisition also exposes pending state and prevents duplicates"));press(c,"Status details:");c.runOnClient(mc->check(mc.gui.screen() instanceof InfoScreen,"Pending import can open retained full status"));}finally{held.countDown();}waitFor(c,nested,active);c.runOnClient(mc->{check(editor().selectedId().equals(nested.id())&&active.fullStatus().contains("selected in draft"),"A retained status child keeps the import owner active");mc.gui.screen().onClose();});c.waitTicks(3);c.runOnClient(mc->{check(mc.gui.screen()==active&&active.path().getValue().equals(nested.path().toString()),"Status return retains the import path and completed result");check(mc.gui.screen().getFocused() instanceof Button b&&b.getMessage().getString().startsWith("Status details:"),"Status return restores its actual opener focus");});c.takeScreenshot("ux13-import-complete-after-status");press(c,"Back to outfit");
        var cancelled=png(0xFF6C9E9D);held=hold(c);CosmeticLoadout[] baseline={null};try{c.runOnClient(mc->{editor().discard();editor().category(CosmeticCategory.CAPE);baseline[0]=editor().draft();path().setValue(cancelled.path().toString());importer().activate();editor().discard();Client.INSTANCE.getClickGui().selectPage(ClickGui.Page.APPEARANCE);});}finally{held.countDown();}waitFor(c,cancelled,editor());c.runOnClient(mc->{check(editor().draft().equals(baseline[0])&&Client.INSTANCE.getClickGui().getPage()==ClickGui.Page.APPEARANCE,"Completion after discard/page leave retains the chosen page and outfit");Client.INSTANCE.getThemeManager().reset();mc.gui.setScreen(null);});Client.INSTANCE.getLogger().info("UX asynchronous import recovery checks passed: {}",checks);
    }
}
